/**
 * test/chain-checkpoints.test.js
 *
 * WO-CARTRIDGE-SEAL part B: chain segments, C2SP signed checkpoints, RFC 9162
 * inclusion and consistency proofs.
 *
 * STAGED, NOT YET LANDED. Every module this needs is core (src/chain,
 * src/store), so it lands only at the owner's signing sitting, as
 * proposals/chain-checkpoints.patch (generated by
 * proposals/make-chain-checkpoints-patch.mjs, never typed). Same shape as
 * test/chain-seq-continuity.test.js:
 *
 *   - FIRST describe: the cases against the LIVE modules. Until the patch
 *     lands they run as TODO and fail (the functions do not exist), which is
 *     the fail-first half. The landing tripwire is src/chain/merkle.js
 *     existing in the live tree.
 *   - SECOND describe: the same cases against the QUEUED PATCH. In a temp
 *     dir it copies today's src/chain and src/store, applies the patch with
 *     git apply, imports the patched modules and runs every case for real.
 *
 * The two controls that pass on today's main are part of the evidence: a
 * key-holder rewrite of a sealed segment verifies { ok: true } under the
 * live verifyChain, and a forged checkpoint parses cleanly when nobody checks
 * its signature. The checkpoint layer is what turns both into failures.
 */

import { describe, it, before, after } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import crypto from 'node:crypto';
import { execFileSync } from 'node:child_process';
import { fileURLToPath, pathToFileURL } from 'node:url';

import * as liveChain from '../src/chain/index.js';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const REPO = path.join(__dirname, '..');
const PATCH_PATH = path.join(REPO, 'proposals', 'chain-checkpoints.patch');
const LANDED = fs.existsSync(path.join(REPO, 'src', 'chain', 'merkle.js'));
const TODO_MSG = 'lands with proposals/chain-checkpoints.patch at the signing sitting';
const NL = String.fromCharCode(10);

const lf = (s) => s.replace(/\r\n/g, '\n');

async function importSet(root) {
  const load = async (...rel) => {
    try {
      return await import(pathToFileURL(path.join(root, ...rel)).href);
    } catch {
      return {};
    }
  };
  return {
    chain: await load('src', 'chain', 'index.js'),
    merkle: await load('src', 'chain', 'merkle.js'),
    cp: await load('src', 'chain', 'checkpoint.js'),
    store: await load('src', 'store', 'index.js'),
    storeCk: await load('src', 'store', 'checkpoints.js')
  };
}

// ---------- helpers (test-side only, no core writes) ----------

function tmpHome(prefix) {
  return fs.mkdtempSync(path.join(os.tmpdir(), prefix));
}

function chainFile(home) {
  return path.join(home, 'receipts', 'chain.jsonl');
}

function sidecarFile(home) {
  return path.join(home, 'receipts', 'checkpoints.jsonl');
}

function sha256File(p) {
  return crypto.createHash('sha256').update(fs.readFileSync(p)).digest('hex');
}

/** Append n receipts through the real store. */
function appendMany(store, n, tag = 'r') {
  for (let i = 0; i < n; i++) store.appendReceipt({ type: 'test', tag, i });
}

function readEntries(home) {
  return fs.readFileSync(chainFile(home), 'utf8').split('\n').filter((l) => l.trim()).map((l) => JSON.parse(l));
}

function writeEntries(home, entries) {
  fs.writeFileSync(chainFile(home), entries.map((e) => JSON.stringify(e) + '\n').join(''));
}

/**
 * A key holder rewrites history: change the payload of entry `at` and
 * re-sign every entry from there with the SAME chain key. The plain chain
 * verify cannot tell, by construction.
 */
function keyHolderRewrite(M, home, keyPair, at) {
  const entries = readEntries(home);
  const kept = entries.slice(0, at);
  const c = M.chain.createChain(keyPair, at, kept);
  c.append({ ...entries[at].payload, rewritten: true });
  for (let i = at + 1; i < entries.length; i++) c.append(entries[i].payload);
  writeEntries(home, c.entries);
}

const SEG = 8; // small segments keep the store cases fast; the 40k case uses the default

// RFC 6962 reference vectors (the eight leaves from the certificate-transparency
// test data, as carried by transparency-dev/merkle), roots for sizes 1..8.
const RFC6962_LEAVES = ['', '00', '10', '2021', '3031', '40414243', '5051525354555657', '606162636465666768696a6b6c6d6e6f'];
const RFC6962_ROOTS = [
  '6e340b9cffb37a989ca544e6bb780a2c78901d3fb33738768511a30617afa01d',
  'fac54203e7cc696cf0dfcb42c92a1d9dbaf70ad9e621f4bd8d98662f00e3c125',
  'aeb6bcfe274b70a14fb067a5e5578264db0fa9b51af5e0ba159158f329e06e77',
  'd37ee418976dd95753c1c73862b9398fa2a2cf9b4ff0fdfe8b30cd95209614b7',
  '4e3bbb1f7b478dcfe71fb631631519a3bca12c9aefca1612bfce4c13a86264d4',
  '76e67dadbcdf1e10e1b74ddc608abd2f98dfb16fbce75277b5232a127f2087ef',
  'ddb89be403809e325750d3d263cd78929c2942b7942a34b77e122c9594a74c8c',
  '5dc9da79a70659a9ad559cb701ded9a2ab9d823aad2f4960cfe370eff4604328'
];

// C2SP signed-note example (c2sp.org/signed-note, "Verifier keys", Example).
// The signature line's leading U+2014 is built, not typed.
const SPEC_VKEY = 'example.com/foo+530d903a+AekyeRrm56hApGFkyQR4ZCbV54Id2LKaANYcrnKv3U2k';
const SPEC_NOTE = 'This is an example message.' + NL + NL + String.fromCharCode(0x2014) +
  ' example.com/foo Uw2QOkn8srV1yJGh2VYRlL1Tnagv1YEq6TfXppzi2ONncAlTgK7Ztg1ERYNZXsYjOBH3mFXmRKuwHjG1Yu72IneyaQM=' + NL;

/**
 * The cases, as { name, fn(M) }. M is a module set from importSet().
 */
function cases() {
  return [
    {
      name: 'merkle: RFC 6962 reference roots for sizes 1..8',
      fn(M) {
        const leaves = RFC6962_LEAVES.map((h) => M.merkle.leafHash(Buffer.from(h, 'hex')));
        for (let n = 1; n <= 8; n++) {
          assert.equal(M.merkle.rootFromLeafHashes(leaves.slice(0, n)).toString('hex'), RFC6962_ROOTS[n - 1], `root of size ${n}`);
        }
        assert.equal(M.merkle.EMPTY_ROOT.toString('hex'), crypto.createHash('sha256').digest('hex'));
      }
    },
    {
      name: 'merkle: every inclusion and consistency proof up to size 40 verifies, and a wrong one does not',
      fn(M) {
        const all = Array.from({ length: 40 }, (_, i) => M.merkle.leafHash(Buffer.from([i, i * 7 % 256])));
        for (let n = 1; n <= 40; n++) {
          const leaves = all.slice(0, n);
          const root = M.merkle.rootFromLeafHashes(leaves);
          for (let m = 0; m < n; m++) {
            const p = M.merkle.inclusionPath(m, leaves);
            assert.ok(M.merkle.verifyInclusion(m, n, leaves[m], p, root), `inclusion ${m}/${n}`);
            if (n > 1) assert.ok(!M.merkle.verifyInclusion((m + 1) % n, n, leaves[m], p, root), `wrong index ${m}/${n}`);
            if (p.length) {
              const bad = p.map((x) => Buffer.from(x));
              bad[0][0] ^= 1;
              assert.ok(!M.merkle.verifyInclusion(m, n, leaves[m], bad, root), `tampered path ${m}/${n}`);
            }
          }
          for (let m = 1; m <= n; m++) {
            const old = M.merkle.rootFromLeafHashes(leaves.slice(0, m));
            const p = M.merkle.consistencyProof(m, leaves);
            assert.ok(M.merkle.verifyConsistency(m, n, old, root, p), `consistency ${m}->${n}`);
            if (m < n) {
              const forkedOld = M.merkle.rootFromLeafHashes([...leaves.slice(0, m - 1), M.merkle.leafHash(Buffer.from('fork'))]);
              assert.ok(!M.merkle.verifyConsistency(m, n, forkedOld, root, p), `forked consistency ${m}->${n}`);
            }
          }
        }
      }
    },
    {
      name: 'merkle: the frontier folds to MTH at every size 0..70',
      fn(M) {
        let f = [];
        const leaves = [];
        assert.ok(M.merkle.frontierRoot(f).equals(M.merkle.EMPTY_ROOT));
        for (let n = 1; n <= 70; n++) {
          const leaf = M.merkle.leafHash(Buffer.from(String(n)));
          f = M.merkle.frontierAppend(f, n - 1, leaf);
          leaves.push(leaf);
          assert.equal(f.length, M.merkle.popcount(n));
          assert.ok(M.merkle.frontierRoot(f).equals(M.merkle.rootFromLeafHashes(leaves)), `size ${n}`);
        }
      }
    },
    {
      name: 'signed note: the C2SP spec example verifies, and one changed byte does not',
      fn(M) {
        const k = M.cp.parseVkey(SPEC_VKEY);
        assert.equal(k.keyId.toString('hex'), '530d903a');
        const v = M.cp.verifyNote(SPEC_NOTE, k.name, k.publicKeyRaw);
        assert.deepEqual(v, { ok: true, text: 'This is an example message.' + NL });
        const tampered = SPEC_NOTE.replace('example message', 'example massage');
        assert.equal(M.cp.verifyNote(tampered, k.name, k.publicKeyRaw).ok, false);
        assert.equal(M.cp.vkey(k.name, k.publicKeyRaw), SPEC_VKEY, 'vkey round-trips');
      }
    },
    {
      name: 'verifyRange from genesis returns exactly what verifyChain returns (live module vs patched module)',
      fn(M) {
        const kp = M.chain.generateKeyPair();
        const pub = crypto.createPublicKey(kp.publicKey);
        const make = () => {
          const c = M.chain.createChain(kp);
          for (let i = 0; i < 6; i++) c.append({ i });
          return c.entries.map((e) => ({ ...e }));
        };
        const variants = [];
        variants.push(make());
        let v = make(); v[3].payload = { i: 99 }; variants.push(v);
        v = make(); v[2].sig = v[2].sig.replace(/^./, (c) => (c === 'a' ? 'b' : 'a')); variants.push(v);
        v = make(); v[4].prevHash = v[1].hash; variants.push(v);
        const skip = M.chain.createChain(kp, 3, make().slice(0, 2)); skip.append({ x: 1 }); variants.push(skip.entries);
        const g = M.chain.createChain(kp, 5); g.append({ x: 1 }); variants.push(g.entries);
        variants.push([]);
        for (const entries of variants) {
          const expected = liveChain.verifyChain(entries, pub);
          assert.deepEqual(M.chain.verifyChain(entries, pub), expected);
          assert.deepEqual(M.chain.verifyRange(entries, pub), expected);
        }
      }
    },
    {
      name: 'verifyRange: a tail verified from a trusted (seq, prevHash) reports absolute seqs',
      fn(M) {
        const kp = M.chain.generateKeyPair();
        const pub = crypto.createPublicKey(kp.publicKey);
        const c = M.chain.createChain(kp);
        for (let i = 0; i < 10; i++) c.append({ i });
        const tail = c.entries.slice(6);
        assert.deepEqual(M.chain.verifyRange(tail, pub, { startSeq: 6, prevHash: c.entries[5].hash }), { ok: true });
        const wrong = M.chain.verifyRange(tail, pub, { startSeq: 6, prevHash: c.entries[4].hash });
        assert.equal(wrong.ok, false);
        assert.equal(wrong.brokenAt, 6);
        assert.match(wrong.reason, /prevHash link broken at entry 6/);
        const off = M.chain.verifyRange(tail, pub, { startSeq: 5, prevHash: c.entries[4].hash });
        assert.equal(off.ok, false);
        assert.match(off.reason, /seq discontinuity at entry 5: expected 5, got 6/);
      }
    },
    {
      name: 'FAIL-FIRST (tamper inside a sealed segment): a key-holder rewrite verifies under verifyChain, and a kept checkpoint catches it',
      fn(M) {
        const home = tmpHome('lotor-ckpt-rewrite-');
        try {
          const store = M.store.createStore(home);
          appendMany(store, 3 * SEG + 3);
          assert.deepEqual(store.seal({ segmentSize: SEG }), { sealed: 3, size: 3 * SEG });
          // A stranger keeps the size-16 checkpoint and a proof for entry 5.
          const keptProof = store.proveInclusion(5, { size: 2 * SEG });
          const kept = keptProof.checkpoint;
          assert.equal(M.cp.verifyInclusionProof(keptProof, store.keyPair.publicKey).ok, true);

          keyHolderRewrite(M, home, store.keyPair, 5);
          fs.rmSync(sidecarFile(home));
          const store2 = M.store.createStore(home);
          store2.seal({ segmentSize: SEG });

          // Control, true on today's main: the rewritten chain verifies, and
          // so does its freshly re-sealed checkpoint set.
          const pub = crypto.createPublicKey(store2.keyPair.publicKey);
          assert.deepEqual(liveChain.verifyChain(readEntries(home), pub), { ok: true });
          assert.equal(store2.verifySealed().ok, true);

          // The kept checkpoint is what catches it.
          const inc = store2.verifyIncremental({ trusted: kept });
          assert.equal(inc.ok, false);
          assert.match(inc.reason, /fork/);
          const newProof = store2.proveInclusion(5, { size: 2 * SEG });
          assert.notEqual(newProof.leaf, keptProof.leaf);
          assert.equal(M.cp.verifyInclusionProof({ ...newProof, checkpoint: kept }, store2.keyPair.publicKey).ok, false);
          const cons = store2.proveConsistency(2 * SEG);
          assert.equal(M.cp.verifyConsistencyProof({ ...cons, from: kept }, store2.keyPair.publicKey).ok, false);
        } finally {
          fs.rmSync(home, { recursive: true, force: true });
        }
      }
    },
    {
      name: 'FAIL-FIRST (tamper inside a sealed segment, no key): full sealed verify and a walk from an earlier checkpoint catch it',
      fn(M) {
        const home = tmpHome('lotor-ckpt-tamper-');
        try {
          const store = M.store.createStore(home);
          appendMany(store, 3 * SEG);
          store.seal({ segmentSize: SEG });
          const first = store.proveInclusion(0, { size: SEG }).checkpoint;
          const lines = fs.readFileSync(chainFile(home), 'utf8').split('\n');
          lines[SEG + 2] = lines[SEG + 2].replace('"tag":"r"', '"tag":"R"');
          fs.writeFileSync(chainFile(home), lines.join('\n'));

          const sealed = store.verifySealed();
          assert.equal(sealed.ok, false);
          assert.match(sealed.reason, /hash mismatch at entry 10/);
          const fromFirst = store.verifyIncremental({ trusted: first });
          assert.equal(fromFirst.ok, false);
          assert.match(fromFirst.reason, /hash mismatch at entry 10/);
          // Documented, not a defect: from the NEWEST checkpoint nothing before
          // it is read, so an edit inside an older sealed segment is out of
          // that walk's sight. That is what "incremental" means; verifySealed
          // and store.verify() are the full reads.
          const fromNewest = store.verifyIncremental();
          assert.equal(fromNewest.ok, true);
          assert.equal(fromNewest.from, 3 * SEG);
        } finally {
          fs.rmSync(home, { recursive: true, force: true });
        }
      }
    },
    {
      name: 'FAIL-FIRST (forged checkpoint): wrong key, edited root, or a forged sidecar note is rejected',
      fn(M) {
        const home = tmpHome('lotor-ckpt-forge-');
        try {
          const store = M.store.createStore(home);
          appendMany(store, 2 * SEG);
          store.seal({ segmentSize: SEG });
          const pub = store.keyPair.publicKey;
          const real = store.proveInclusion(1).checkpoint;
          const origin = M.cp.originFor(pub);
          const cp = M.cp.parseCheckpointText(real.slice(0, real.lastIndexOf(NL + NL) + 1));

          // (1) Same origin and tree, signed by a different key.
          const other = M.chain.generateKeyPair();
          const text = M.cp.checkpointText(origin, cp.size, cp.root);
          const forgedSig = text + NL + String.fromCharCode(0x2014) + ' ' + origin + ' ' +
            Buffer.concat([M.cp.keyId(origin, M.cp.rawPublicKey(pub)), crypto.sign(null, Buffer.from(text), other.privateKey)]).toString('base64') + NL;
          // (2) The real signature over an edited root.
          const editedRoot = Buffer.from(cp.root); editedRoot[0] ^= 1;
          const forgedRoot = real.replace(cp.root.toString('base64'), editedRoot.toString('base64'));

          for (const forged of [forgedSig, forgedRoot]) {
            // Control: without the signature check, the forgery is a fine checkpoint.
            const body = M.cp.parseCheckpointText(forged.slice(0, forged.lastIndexOf(NL + NL) + 1));
            assert.ok(body && body.size === cp.size, 'a signature-skipping reader would accept this');
            assert.equal(M.cp.verifyCheckpoint(forged, pub).ok, false);
          }

          // (3) A forged note planted in the sidecar: readers and the sealer refuse it.
          const recs = fs.readFileSync(sidecarFile(home), 'utf8').split('\n').filter(Boolean).map((l) => JSON.parse(l));
          recs[1].note = forgedSig.replace(NL + cp.size + NL, NL + recs[1].size + NL);
          fs.writeFileSync(sidecarFile(home), recs.map((r) => JSON.stringify(r) + '\n').join(''));
          assert.equal(store.verifyIncremental().ok, false);
          assert.equal(store.verifySealed().ok, false);
          appendMany(store, SEG);
          assert.throws(() => store.seal({ segmentSize: SEG }), /checkpoint at size 16/);
          assert.throws(() => store.proveInclusion(1), /does not match its own checkpoint|checkpoint/);
        } finally {
          fs.rmSync(home, { recursive: true, force: true });
        }
      }
    },
    {
      name: 'FAIL-FIRST (proof against the wrong checkpoint): another size, a forged size, or another chain fails',
      fn(M) {
        const home = tmpHome('lotor-ckpt-wrong-');
        const home2 = tmpHome('lotor-ckpt-wrong2-');
        try {
          const store = M.store.createStore(home);
          appendMany(store, 2 * SEG);
          store.seal({ segmentSize: SEG });
          const pub = store.keyPair.publicKey;
          const p8 = store.proveInclusion(3, { size: SEG });
          const p16 = store.proveInclusion(3, { size: 2 * SEG });
          assert.equal(M.cp.verifyInclusionProof(p8, pub).ok, true);
          assert.equal(M.cp.verifyInclusionProof(p16, pub).ok, true);

          const mixed = M.cp.verifyInclusionProof({ ...p8, checkpoint: p16.checkpoint }, pub);
          assert.equal(mixed.ok, false);
          assert.match(mixed.reason, /tree size 8, checkpoint is size 16/);
          const resized = M.cp.verifyInclusionProof({ ...p8, size: 2 * SEG, checkpoint: p16.checkpoint }, pub);
          assert.equal(resized.ok, false);
          assert.match(resized.reason, /is not at index 3/);
          const otherLeaf = M.cp.verifyInclusionProof({ ...p16, index: 4 }, pub);
          assert.equal(otherLeaf.ok, false);

          const store2 = M.store.createStore(home2);
          appendMany(store2, 2 * SEG);
          store2.seal({ segmentSize: SEG });
          const foreign = store2.proveInclusion(3, { size: SEG });
          assert.equal(M.cp.verifyInclusionProof(foreign, pub).ok, false, 'a proof from another chain fails under this key');
          assert.equal(M.cp.verifyInclusionProof({ ...p8, checkpoint: foreign.checkpoint }, store2.keyPair.publicKey).ok, false);
        } finally {
          fs.rmSync(home, { recursive: true, force: true });
          fs.rmSync(home2, { recursive: true, force: true });
        }
      }
    },
    {
      name: 'a head checkpoint on demand proves the newest receipt now, and segment boundaries stay on multiples',
      fn(M) {
        const home = tmpHome('lotor-ckpt-head-');
        try {
          const store = M.store.createStore(home);
          appendMany(store, 2 * SEG + 3);
          assert.deepEqual(store.seal({ segmentSize: SEG }), { sealed: 2, size: 2 * SEG });
          assert.throws(() => store.proveInclusion(2 * SEG + 2), /not covered/);
          assert.deepEqual(store.seal({ segmentSize: SEG, atHead: true }), { sealed: 1, size: 2 * SEG + 3 });
          const p = store.proveInclusion(2 * SEG + 2);
          assert.equal(M.cp.verifyInclusionProof(p, store.keyPair.publicKey).ok, true);
          assert.deepEqual(store.seal({ segmentSize: SEG, atHead: true }), { sealed: 0, size: 2 * SEG + 3 }, 'nothing new, nothing sealed');
          appendMany(store, SEG);
          assert.deepEqual(store.seal({ segmentSize: SEG }), { sealed: 1, size: 3 * SEG }, 'the next segment ends on the multiple');
          const recs = fs.readFileSync(sidecarFile(home), 'utf8').split('\n').filter(Boolean).map((l) => JSON.parse(l));
          assert.deepEqual(recs.map((r) => r.size), [SEG, 2 * SEG, 2 * SEG + 3, 3 * SEG]);
          assert.equal(store.verifySealed().ok, true);
          // The older head checkpoint is still consistent with the newer tree.
          const cons = store.proveConsistency(2 * SEG + 3);
          assert.equal(M.cp.verifyConsistencyProof(cons, store.keyPair.publicKey).ok, true);
          // Re-sealing from scratch reproduces byte-identical notes (Ed25519 is
          // deterministic and the note text is fixed by size and root), so a
          // stranger's kept checkpoint survives a lost sidecar.
          const notes = recs.map((r) => r.note);
          fs.rmSync(sidecarFile(home));
          store.seal({ segmentSize: SEG });
          const again = fs.readFileSync(sidecarFile(home), 'utf8').split('\n').filter(Boolean).map((l) => JSON.parse(l).note);
          assert.deepEqual(again, [notes[0], notes[1], notes[3]]);
        } finally {
          fs.rmSync(home, { recursive: true, force: true });
        }
      }
    },
    {
      name: 'sidecar caches fail closed: an edited frontier, an edited lastHash, or a truncated chain',
      fn(M) {
        const home = tmpHome('lotor-ckpt-cache-');
        try {
          const store = M.store.createStore(home);
          appendMany(store, 2 * SEG + 2);
          store.seal({ segmentSize: SEG });
          const original = fs.readFileSync(sidecarFile(home), 'utf8');
          const edit = (fn) => {
            const recs = original.split('\n').filter(Boolean).map((l) => JSON.parse(l));
            fn(recs[recs.length - 1]);
            fs.writeFileSync(sidecarFile(home), recs.map((r) => JSON.stringify(r) + '\n').join(''));
          };
          edit((r) => { r.frontier[0] = '0'.repeat(64); });
          assert.match(store.verifyIncremental().reason, /frontier does not fold/);
          edit((r) => { r.lastHash = '1'.repeat(64); });
          assert.match(store.verifyIncremental().reason, /lastHash is not leaf 15/);
          fs.writeFileSync(sidecarFile(home), original);
          assert.equal(store.verifyIncremental().ok, true);

          const lines = fs.readFileSync(chainFile(home), 'utf8').split('\n').filter(Boolean);
          fs.writeFileSync(chainFile(home), lines.slice(0, SEG + 3).map((l) => l + '\n').join(''));
          const t = store.verifyIncremental();
          assert.equal(t.ok, false);
          assert.match(t.reason, /truncated/);
          assert.equal(store.verifySealed().ok, false);
        } finally {
          fs.rmSync(home, { recursive: true, force: true });
        }
      }
    },
    {
      name: 'FAIL-FIRST (migration): a 40,000-entry chain is sealed without changing a byte, and every entry hash is reproduced',
      fn(M) {
        // Fail fast where the feature is absent, before building 40k entries.
        const N = M.storeCk.SEGMENT_SIZE;
        assert.equal(N, 1024);
        const home = tmpHome('lotor-ckpt-40k-');
        try {
          const store = M.store.createStore(home);
          // Build the fixture with the chain module's own writer and the
          // store's on-disk line format (JSON + LF), as a real chain was written.
          const c = M.chain.createChain(store.keyPair);
          for (let i = 0; i < 40000; i++) c.append({ type: 'fixture', i, tool: i % 3 ? 'Bash' : 'Edit' });
          writeEntries(home, c.entries);
          const before = sha256File(chainFile(home));
          const hashes = c.entries.map((e) => e.hash);

          const res = store.seal();
          assert.deepEqual(res, { sealed: Math.floor(40000 / N), size: Math.floor(40000 / N) * N });

          assert.equal(sha256File(chainFile(home)), before, 'chain.jsonl is byte-identical after migration');
          assert.deepEqual(readEntries(home).map((e) => e.hash), hashes, 'every entry hash is reproduced');
          const recs = fs.readFileSync(sidecarFile(home), 'utf8').split('\n').filter(Boolean).map((l) => JSON.parse(l));
          assert.equal(recs[0].size, N, 'the first checkpoint covers seq 0..N-1 of the existing file');
          assert.deepEqual(store.verifySealed(), { ok: true, mode: 'full', from: 0, size: 40000, checkpoints: recs.length });
          assert.deepEqual(store.verifyIncremental(), { ok: true, mode: 'incremental', from: res.size, size: 40000 });

          const pub = store.keyPair.publicKey;
          for (const seq of [0, 1, 1023, 1024, 20000, res.size - 1]) {
            const p = store.proveInclusion(seq);
            assert.equal(p.leaf, hashes[seq]);
            assert.equal(M.cp.verifyInclusionProof(p, pub).ok, true, `proof for ${seq}`);
          }
          assert.throws(() => store.proveInclusion(res.size), /not covered/);

          // Measurement for the cartridge follow-on (not asserted).
          const p = store.proveInclusion(20000);
          const noteBytes = Buffer.byteLength(p.checkpoint);
          const compactFirst = 4 + 4 + 32 * p.path.length + 32 + 64; // index, size, path, root, sig
          const compactNext = 4 + 32 * p.path.length;
          console.log(`  40k chain: path ${p.path.length} hashes; note ${noteBytes} B; compact first proof ${compactFirst} B, each further proof ${compactNext} B`);
        } finally {
          fs.rmSync(home, { recursive: true, force: true });
        }
      }
    }
  ];
}

