describe('queued patch: proposals/chain-checkpoints.patch', () => {
  if (LANDED) {
    it('the staged patch is already landed', { skip: 'src/chain/merkle.js is live; nothing left to rehearse' }, () => {});
    return;
  }

  let tmp;
  let patched;

  before(async () => {
    // Rehearse the landing: today's core source (CRLF folded to LF, the
    // house patch format), plus exactly the staged diff, in a throwaway repo.
    tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'chain-checkpoints-'));
    for (const dir of [['src', 'chain'], ['src', 'store']]) {
      fs.mkdirSync(path.join(tmp, ...dir), { recursive: true });
      for (const name of fs.readdirSync(path.join(REPO, ...dir))) {
        const text = fs.readFileSync(path.join(REPO, ...dir, name), 'utf8');
        fs.writeFileSync(path.join(tmp, ...dir, name), lf(text));
      }
    }
    fs.writeFileSync(path.join(tmp, 'b.patch'), lf(fs.readFileSync(PATCH_PATH, 'utf8')));
    execFileSync('git', ['init', '-q'], { cwd: tmp });
    execFileSync('git', ['apply', 'b.patch'], { cwd: tmp });
    patched = await importSet(tmp);
    assert.equal(typeof patched.storeCk.sealCheckpoints, 'function', 'the patched store exposes sealCheckpoints');
  });
  after(() => { if (tmp) fs.rmSync(tmp, { recursive: true, force: true }); });

  it('the staged patch applies cleanly to today\'s source', () => {
    assert.ok(patched);
  });

  it('the patch adds the three new core files and touches only src/chain and src/store', () => {
    const text = lf(fs.readFileSync(PATCH_PATH, 'utf8'));
    const targets = text.split('\n').filter((l) => l.startsWith('+++ ')).map((l) => l.slice(4));
    assert.deepEqual(targets.sort(), [
      'b/src/chain/checkpoint.js',
      'b/src/chain/index.js',
      'b/src/chain/merkle.js',
      'b/src/store/checkpoints.js',
      'b/src/store/index.js'
    ]);
    assert.equal(text.includes(String.fromCharCode(0x2014)), false, 'the patch carries no U+2014 byte');
  });

  for (const c of cases()) {
    it(c.name, {}, () => c.fn(patched));
  }
});
